#!/usr/bin/env python3
from pathlib import Path
import base64,json,zlib
PAYLOAD='''[... ELLIPSIZATION ...]'''
files=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode())
for rel,text in files.items():
    p=Path(rel);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
print(f'Materialized {len(files)} frozen R26 source/audit files')
